export default "/* strategy.css — domain residue for com.ikenga.strategy.\n *\n * Only strategy-local classes live here:\n *   - .ux-dot(.ux-confirm|.ux-silent|.ux-approve) / .next-chip / .stage-chip — small\n *     shared status-dot / chip residue (app-kit ships the .pl-*/.okr-*/.kb-* chrome;\n *     these tiny shell-ish primitives are kept per-domain, as in content.css).\n *   - .st-mv-wrap / .fc-kpis / .fc-kpi* — Cycles + Reviews KPI cells (4-up grid)\n *   - .st-cycle-row / .st-cycle-head / .st-cycle-name / .st-cycle-meta / .st-prog — Cycles view\n *   - .st-mv-table / .st-mv-badge / .st-status-pill — Reviews table + cadence chips\n *   - Reduced-motion overrides for strategy-specific transitions\n *\n * Kit primitives (.frame*, .pane-split, .pl-*, .kb-*, .okr-*, .kb-col-agg, .btn*,\n * .tag, .chip, .badge, .atelier-state*, .nav-group*, .nav-item*, .seg*) are\n * consumed from app-kit-css.js — never re-derived here.\n *\n * Inject order: tokens-css → app-kit-css → strategy-css (this file).\n * data-workspace=\"settings\" on <html> → cool slate-blue tint for active nav + accents.\n * No new tokens — only var(--*) from @ikenga/tokens. Per the screen doc §4 step 8:\n * ~80 lines, layout-only, all Cycles/Reviews/detail residue.\n */\n\n/* ── Reduced motion gate ── */\n@media (prefers-reduced-motion: reduce) {\n  .kb-card { transition: none; }\n  .kb-card:hover { transform: none; }\n  .pl-row { transition: none; }\n}\n\n/* ── Area column dot colours: passed inline on .kb-col-dot (kanban convention) ──\n   so no per-area CSS here; the tolerant-extras column gets a neutral dot only. */\n.kb-col:not([data-stage=\"Company\"]):not([data-stage=\"Growth\"]):not([data-stage=\"Product\"]):not([data-stage=\"Finance\"]) .kb-col-dot {\n  background: var(--fg-faint, rgba(128,128,128,0.3));\n}\n\n/* ── UX-mode dots (strategy domain) ────────────────────────────────────────────\n   ux-confirm = achievement (operator confirms) · ux-silent = fg-faint (agent acts\n   autonomously) · ux-approve = primary (operator countersigns). Mirrors content.css. */\n.ux-dot {\n  display: inline-block;\n  width: 7px;\n  height: 7px;\n  border-radius: 50%;\n  flex-shrink: 0;\n  margin-right: 4px;\n}\n.ux-dot.ux-confirm { background: var(--achievement, hsl(38,85%,52%)); }\n.ux-dot.ux-silent  { background: var(--fg-faint, rgba(128,128,128,0.4)); }\n.ux-dot.ux-approve { background: var(--primary, hsl(215,70%,55%)); }\n\n/* ── Next-action chip (board + list rows + detail) ─────────────────────────────── */\n.next-chip {\n  display: inline-flex;\n  align-items: center;\n  gap: 3px;\n  font-size: 0.68rem;\n  color: var(--fg-muted);\n  background: var(--bg-inset, rgba(0,0,0,0.06));\n  border-radius: 4px;\n  padding: 2px 6px;\n  max-width: 220px;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n/* ── Stage / area chip in detail eyebrow ───────────────────────────────────────── */\n.stage-chip {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  font-size: 0.7rem;\n  font-weight: 600;\n  padding: 3px 8px;\n  border-radius: 5px;\n  background: var(--bg-inset, rgba(0,0,0,0.07));\n  color: var(--fg-muted);\n  text-transform: capitalize;\n  letter-spacing: 0.03em;\n}\n\n/* ── Hot filter (At risk — achievement amber count) ────────────────────────────── */\n.nav-item.is-hot .nav-item-count {\n  color: var(--achievement, hsl(38,85%,52%));\n  font-weight: 700;\n}\n\n/* ── Affirmative button (approve actions, live-tinted) ─────────────────────────── */\n.btn.affirmative {\n  border-color: color-mix(in srgb, var(--live, hsl(348,72%,52%)) 45%, transparent);\n  color: var(--live, hsl(348,72%,52%));\n}\n\n/* ── Cycles + Reviews secondary-view wrapper + KPI cells (.st-* / .fc-*) ────────── */\n.st-mv-wrap { padding: var(--space-5); display: grid; gap: var(--space-5); align-content: start; overflow: auto; height: 100%; }\n.fc-kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: var(--space-3); }\n.fc-kpi { border: 1px solid var(--border-soft); border-radius: var(--radius-md); padding: var(--space-3) var(--space-4); background: var(--bg-base); }\n.fc-kpi-k { font-family: var(--font-mono); font-size: 10px; letter-spacing: .08em; text-transform: uppercase; color: var(--fg-faint); }\n.fc-kpi-v { font-family: var(--font-display); font-size: 26px; font-weight: 500; margin-top: 4px; }\n.fc-kpi-sub { font-size: 11px; color: var(--fg-muted); margin-top: 2px; }\n\n.st-fc-card { border: 1px solid var(--border-soft); border-radius: var(--radius-md); padding: var(--space-4); background: var(--bg-base); }\n.st-fc-card.flush { padding: 0; overflow: hidden; }\n.st-fc-card-h { font-family: var(--font-display); font-size: 15px; font-weight: 500; margin-bottom: var(--space-4); display: flex; justify-content: space-between; align-items: baseline; }\n.st-fc-card-h .st-sub { font-family: var(--font-mono); font-size: 10px; color: var(--fg-faint); letter-spacing: .06em; text-transform: uppercase; }\n\n/* ── Cycles view: cycle cards + 6px progress bar ───────────────────────────────── */\n.st-cycle-row { border: 1px solid var(--border-soft); border-radius: var(--radius-md); padding: var(--space-4); background: var(--bg-base); display: grid; gap: 8px; }\n.st-cycle-row.cur { border-color: color-mix(in srgb, var(--primary) 45%, transparent); }\n.st-cycle-head { display: flex; align-items: center; justify-content: space-between; gap: var(--space-3); }\n.st-cycle-name { font-family: var(--font-display); font-size: 15px; font-weight: 500; }\n.st-cycle-meta { font-size: 11px; color: var(--fg-faint); font-family: var(--font-mono); }\n.st-prog { height: 6px; border-radius: 3px; background: var(--bg-sunken); overflow: hidden; margin-top: 4px; }\n.st-prog-fill { height: 100%; background: linear-gradient(90deg, var(--primary-soft, var(--primary)), var(--primary)); border-radius: 3px; }\n\n/* ── Status pill (cycles + reviews) ────────────────────────────────────────────── */\n.st-status-pill { font-family: var(--font-mono); font-size: 9px; letter-spacing: .05em; text-transform: uppercase; padding: 2px 7px; border-radius: var(--radius-pill); border: 1px solid var(--border-soft); white-space: nowrap; }\n.st-status-pill.ok { color: var(--live); }\n.st-status-pill.warn { color: var(--primary); }\n.st-status-pill.done { color: var(--achievement); }\n.st-status-pill.muted { color: var(--fg-faint); }\n\n/* ── Reviews view: cadence table + badge chips ─────────────────────────────────── */\n.st-mv-table { width: 100%; border-collapse: collapse; }\n.st-mv-table th { text-align: left; font-family: var(--font-mono); font-size: 10px; letter-spacing: .06em; text-transform: uppercase; color: var(--fg-faint); padding: 10px var(--space-4); border-bottom: 1px solid var(--border-soft); background: var(--bg-sunken); font-weight: 400; }\n.st-mv-table td { padding: 12px var(--space-4); border-bottom: 1px solid var(--border-soft); font-size: var(--text-body-sm); color: var(--fg-muted); }\n.st-mv-table tr:last-child td { border-bottom: 0; }\n.st-mv-table .lead { color: var(--fg); font-weight: 500; }\n.st-mv-badge { font-family: var(--font-mono); font-size: 9px; letter-spacing: .05em; text-transform: uppercase; padding: 2px 7px; border-radius: var(--radius-pill); border: 1px solid var(--border-soft); color: var(--fg-faint); white-space: nowrap; }\n.st-mv-badge.live { color: var(--live); }\n.st-mv-badge.warn { color: var(--primary); }\n.st-mv-badge.gold { color: var(--achievement); }\n"
